function M({registerIndicator:s,sourceValues:r,sma:u,nulls:d}){s({id:"oa-maape",name:"Mean Arctangent Absolute Percentage Error",category:"Errors",placement:"pane",inputs:[{key:"length",type:"number",label:"Length",default:14,min:1,max:5e3,step:1},{key:"actual",type:"source",label:"Actual",default:"close"},{key:"predicted",type:"source",label:"Predicted",default:"open"}],plots:[{key:"maape",type:"line",title:"MAAPE",style:{color:"#ffeb3b",lineWidth:2},priceFormat:{type:"percent"}}],levels:()=>[{price:0,title:"Zero",color:"#787b86",dashed:!0},{price:Math.PI/2,title:"Max (pi/2)",color:"#ff5252",dashed:!0}],calc(t,a){const h=Math.max(1,Math.floor(Number(a.length)||14)),l=r(t,a.actual??"close"),n=r(t,a.predicted??"open"),b=1e-10,m=Math.PI/2,o=t.length,c=new Array(o).fill(NaN);for(let e=0;e<o;e++){const p=Number.isFinite(l[e])?l[e]:0,f=Number.isFinite(n[e])?n[e]:0,i=Math.abs(p),y=Math.abs(p-f);c[e]=i>b?Math.atan(y/i):m}return{maape:d(u(c,h))}}})}export{M as default};
